// ---- KIT común: Robot Trust Gold Mr. Y (imagen oficial desde el 26 nov 2026), outro (seguir/notificaciones/Telegram/web), tarjeta final ----
const ROB=new Image();ROB.src='data:image/png;base64,';
const _s=s=>(typeof NOACC!=='undefined'&&NOACC)?String(s).replace(/≈/g,'~').replace(/→/g,'>').replace(/−/g,'-').normalize('NFD').replace(/(?<![Nn])[\u0300-\u036f]/g,'').normalize('NFC'):s;
function lbl(s,x,y,sz,col,a=1,al='center',fam){s=_s(s);T(s,x,y,{font:`${typeof FW!=='undefined'?FW:900} ${sz}px ${fam||FAM}`,fill:col,a,align:al})}
function fade(t,a,b){return Math.min(prog(t,a,a+.35),1-prog(t,b-.3,b))}
function robot(x,y,h,a=1){const w=h*ROB.width/ROB.height;ctx.save();ctx.globalAlpha*=a;ctx.drawImage(ROB,x,y,w,h);ctx.restore();return w}
function ctaCard(t,st){const CT=SPEC.cta;const k=eout(prog(t,CT,CT+.7));if(k<=0)return;ctx.save();ctx.globalAlpha=k;const V=window.CTA_VIDEO;if(!V){ctx.fillStyle=DK;ctx.fillRect(0,0,W,H);
  const g=ctx.createRadialGradient(540,520,60,540,520,560);g.addColorStop(0,ACC+'73');g.addColorStop(1,ACC+'00');ctx.fillStyle=g;ctx.fillRect(0,0,W,H)}
  const y=lerp(40,0,k);if(!V)robot(540-.5*ROB.width/ROB.height*780,90+y,780,1);
  T('ROBOT',540,925+y,{font:'800 46px Inter',fill:'#f4efe2',glow:ACC,gb:16});
  T('TRUST GOLD',540,1015+y,{font:'900 92px Inter',fill:'#fff',glow:ACC,gb:20});
  T('MR. Y',540,1125+y,{font:'900 92px Inter',fill:ACC,glow:ACC,gb:24});
  RR(240,1200+y,600,96,48);ctx.fillStyle=ACC;ctx.fill();T('LINK EN BIO',540,1250+y,{font:'800 46px Inter',fill:DK});
  T('@forexmry',540,1360+y,{font:'800 48px Inter',fill:'#f4efe2'});ctx.restore()}
function icon(kind,cx,cy){ctx.save();ctx.translate(cx,cy);ctx.lineWidth=5;ctx.strokeStyle='#fff';ctx.fillStyle='#fff';ctx.lineCap='round';ctx.lineJoin='round';
  if(kind==0){RR(-22,-22,44,44,12);ctx.stroke();ctx.beginPath();ctx.arc(0,0,10,0,7);ctx.stroke();ctx.beginPath();ctx.arc(14,-14,3,0,7);ctx.fill()}
  else if(kind==1){ctx.beginPath();ctx.moveTo(-18,12);ctx.quadraticCurveTo(-18,-4,-12,-14);ctx.quadraticCurveTo(0,-30,12,-14);ctx.quadraticCurveTo(18,-4,18,12);ctx.closePath();ctx.fill();ctx.beginPath();ctx.arc(0,20,6,0,7);ctx.fill()}
  else if(kind==2){ctx.beginPath();ctx.moveTo(-24,-2);ctx.lineTo(24,-22);ctx.lineTo(12,22);ctx.lineTo(-2,8);ctx.lineTo(-8,22);ctx.lineTo(-10,6);ctx.closePath();ctx.fill()}
  else{ctx.beginPath();ctx.arc(0,0,22,0,7);ctx.stroke();ctx.beginPath();ctx.ellipse(0,0,10,22,0,0,7);ctx.stroke();line(-22,0,22,0,'#fff',4)}
  ctx.restore()}
function outro(t,a){ctx.save();ctx.globalAlpha=a;ctx.fillStyle=DK;ctx.fillRect(0,0,W,H);
  const g=ctx.createRadialGradient(290,800,60,290,800,560);g.addColorStop(0,ACC+'66');g.addColorStop(1,ACC+'00');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
  const kr=eout(prog(t,50.0,50.8));robot(-20+lerp(-60,0,kr),340,1020,kr);
  lbl('ÚNETE A LA COMUNIDAD',540,290,52,ACC,eout(prog(t,50.0,50.6)),'center','Inter');
  const R=[[51.0,'#c13584','SÍGUENOS','@forexmry en Instagram'],[52.2,'#e0a020','ACTIVA LAS','NOTIFICACIONES'],[53.4,'#2a9bd8','GRUPO DE TELEGRAM','únete a la comunidad'],[54.6,'#2f8a5a','www.robotsdeforexmry.com','visita la página']];
  R.forEach(([ts,col,h,s],i)=>{const k=eout(prog(t,ts,ts+.5));if(k<=0)return;const y=420+i*215;ctx.save();ctx.globalAlpha=a*k;ctx.translate(lerp(60,0,k),0);
    RR(470,y,560,185,28);ctx.fillStyle='#1b1b24';ctx.fill();ctx.lineWidth=4;ctx.strokeStyle=ACC;ctx.stroke();ctx.beginPath();ctx.arc(550,y+92,50,0,7);ctx.fillStyle=col;ctx.fill();icon(i,550,y+92);
    const big=i==3?24:(i==2?32:42);lbl(h,620,y+(i==1?66:80),big,'#fff',1,'left','Inter');if(i==1){lbl(s,620,y+118,42,ACC,1,'left','Inter')}else lbl(s,620,y+(i==3?118:128),30,'#d9d9e3',1,'left','Inter');ctx.restore()});
  ctx.restore()}
// botón de carátula
function coverBtn(txt,col,tc){ctx.save();ctx.fillStyle=col;RR(170,1440,740,110,55);ctx.fill();ctx.restore();T(txt,540,1498,{font:'900 50px Inter',fill:tc})}
// la voz usa la ventana de cada sub; ready
Promise.all([...(window.FONTS||[]).map(f=>document.fonts.load(f)),document.fonts.load('800 40px Inter'),document.fonts.load('900 40px Inter'),new Promise(r=>{ROB.onload=r;ROB.onerror=r})]).then(()=>{window.__ready=true});

